# cyclicity.py -- Theorem 9 (cyclicity), checked directly on the K side:
#   K_d = ker(D: Sym^d -> Sym^{d+1}),  D h_k = sum_{i+j=k, i,j>=1} h_i h_j,
#   K_d = U(S).T_d,  S generated by L_1, L_2,  L_k h_m = (m-k) h_{m-k}.
# Method: integer (fmpz) linear algebra. T_d = primitive integer generator of the 1-dim kernel at weight d^2.
# W_n := span(L_1 W_{n+1} + L_2 W_{n+2}) kept as an integer row basis via fraction-free rref.
# Exact over Q (rank over Z = rank over Q). Checks per weight n:
#   (1) D(W_n) = 0,  (2) rank W_n = dim K_{n,d},  (3) dim K_{n,d} = [q^n] q^d [2d,d]_q/[d+1]_q,
#   (4) dim K_{n,d} = 0 for n > d^2.
# Usage: python cyclicity.py exact <dmin> <dmax>      e.g. exact 1 7 (d = 7 takes ~13 minutes)
#        python cyclicity.py modp <dmin> <dmax> <p>   (mod-p certificate:
#        dim_Q W >= dim_p W = dim_p ker >= dim_Q ker >= dim_Q W)
import sys, time
from math import gcd
import flint

def parts(n, k, mx=None):
    if mx is None: mx = n
    if k == 0:
        if n == 0: yield ()
        return
    for a in range(min(mx, n - k + 1), 0, -1):
        for r in parts(n - a, k - 1, a):
            yield (a,) + r

_B = {}
def B(n, d):
    if (n, d) not in _B:
        L = list(parts(n, d)) if n >= d >= 1 else ([()] if n == d == 0 else [])
        _B[(n, d)] = (L, {p: i for i, p in enumerate(L)})
    return _B[(n, d)]

def D_entries(n, d):
    src, _ = B(n, d); tgt, ti = B(n, d + 1)
    ent = {}
    for j, lam in enumerate(src):
        for pos in range(len(lam)):
            k = lam[pos]
            rest = lam[:pos] + lam[pos + 1:]
            for a in range(1, k):
                key = (ti[tuple(sorted(rest + (a, k - a), reverse=True))], j)
                ent[key] = ent.get(key, 0) + 1
    return ent, len(tgt), len(src)

def L_entries(k, n, d):
    src, _ = B(n, d); tgt, ti = B(n - k, d)
    ent = {}
    for j, lam in enumerate(src):
        for pos in range(len(lam)):
            m = lam[pos]
            if m - k >= 1:
                nl = tuple(sorted(lam[:pos] + (m - k,) + lam[pos + 1:], reverse=True))
                key = (ti[nl], j)
                ent[key] = ent.get(key, 0) + (m - k)
    return ent, len(tgt), len(src)

def tomat(ent, r, c, ring):
    M = ring(r, c)
    for (i, j), v in ent.items():
        M[i, j] = v
    return M

def qbinom(n, k):
    # Gaussian binomial as integer coefficient list
    if k < 0 or k > n: return [0]
    num = [1]
    for i in range(k):
        # multiply by (1 - q^{n-i}) / (1 - q^{i+1})
        a = [0] * (len(num) + n - i)
        for e, c in enumerate(num):
            a[e] += c; a[e + n - i] -= c
        # divide by (1 - q^{i+1})
        m = i + 1; out = list(a)
        for e in range(len(out)):
            if e >= m: out[e] += out[e - m]
        while len(out) > 1 and out[-1] == 0: out.pop()
        num = out
    return num

def theoremC(d):
    a = qbinom(2 * d, d); b = qbinom(2 * d, d + 1)
    c = [0] * (max(len(a), len(b) + 1))
    for e, x in enumerate(a): c[e] += x
    for e, x in enumerate(b): c[e + 1] -= x
    return {e + d: x for e, x in enumerate(c) if x}   # q^d ([2d,d] - q[2d,d+1]) = q^d [2d,d]/[d+1]

def rowreduce_int(rows, ncols):
    rows = [r for r in rows if any(r)]
    if not rows: return []
    M = flint.fmpz_mat(len(rows), ncols, [x for r in rows for x in r])
    R, den, rk = M.rref()
    out = []
    for i in range(rk):
        v = [int(R[i, j]) for j in range(ncols)]
        g = 0
        for x in v:
            g = gcd(g, x)
        out.append([x // g for x in v])
    return out

def apply(ent, r, vec):
    out = [0] * r
    for (i, j), v in ent.items():
        if vec[j]: out[i] += v * vec[j]
    return out

def run_exact(d):
    t0 = time.time()
    C = theoremC(d)
    ok = True
    # kernel dims
    kd = {}
    for n in range(d, d * d + 3):
        src, _ = B(n, d)
        if not src: kd[n] = 0; continue
        ent, r, c = D_entries(n, d)
        rk = tomat(ent, r, c, flint.fmpz_mat).rank() if r else 0
        kd[n] = c - rk
        if kd[n] != C.get(n, 0):
            ok = False; print("THEOREM C MISMATCH", d, n, kd[n], C.get(n, 0))
    # T_d
    N = d * d
    ent, r, c = D_entries(N, d)
    X, nul = tomat(ent, r, c, flint.fmpz_mat).nullspace()
    assert nul == 1, nul
    T = [int(X[i, 0]) for i in range(c)]
    W = {N: rowreduce_int([T], c), N + 1: [], N + 2: []}
    dims = []
    for n in range(N - 1, d - 1, -1):
        rows = []
        for k in (1, 2):
            if n + k > N: continue
            Le, r, c2 = L_entries(k, n + k, d)
            for v in W[n + k]:
                rows.append(apply(Le, r, v))
        ncols = len(B(n, d)[0])
        W[n] = rowreduce_int(rows, ncols) if ncols else []
        # W in K
        if W[n] and B(n, d + 1)[0]:
            De, r, c3 = D_entries(n, d)
            for v in W[n]:
                if any(apply(De, r, v)):
                    ok = False; print("W NOT IN K", d, n)
                    break
        if len(W[n]) != kd.get(n, 0):
            ok = False; print("CYCLICITY FAILS", d, n, len(W[n]), kd.get(n, 0))
        W.pop(n + 2, None)
        dims.append(len(W[n]))
    dims = [len(rowreduce_int([T], len(T)))] + dims
    dims.reverse()
    print(f"d={d} exact: span dims n={d}..{N}: {dims}")
    print(f"d={d} kernel dims match Theorem C and span: {ok}  ({time.time()-t0:.1f}s)")
    return ok

def run_modp(d, p):
    t0 = time.time()
    C = theoremC(d)
    ok = True
    N = d * d
    ent, r, c = D_entries(N, d)
    M = tomat(ent, r, c, lambda a, b: flint.nmod_mat(a, b, p))
    # nullspace mod p
    X, nul = M.nullspace()
    assert nul == 1, ("mod p top kernel dim", nul)
    T = [int(X[i, 0]) for i in range(c)]
    W = {N: [T]}
    dims = [1]
    for n in range(N - 1, d - 1, -1):
        rows = []
        for k in (1, 2):
            if n + k > N: continue
            Le, r2, c2 = L_entries(k, n + k, d)
            for v in W.get(n + k, []):
                rows.append([x % p for x in apply(Le, r2, v)])
        ncols = len(B(n, d)[0])
        rows = [rr for rr in rows if any(rr)]
        if rows and ncols:
            A = flint.nmod_mat(len(rows), ncols, [x for rr in rows for x in rr], p)
            R, rk = A.rref()
            W[n] = [[int(R[i, j]) for j in range(ncols)] for i in range(rk)]
        else:
            W[n] = []
        # mod-p kernel dim at (n,d)
        if B(n, d + 1)[0]:
            De, r3, c3 = D_entries(n, d)
            kp = c3 - tomat(De, r3, c3, lambda a, b: flint.nmod_mat(a, b, p)).rank()
        else:
            kp = ncols
        if len(W[n]) != kp or kp != C.get(n, 0):
            ok = False; print("MODP MISMATCH", d, n, len(W[n]), kp, C.get(n, 0))
        W.pop(n + 2, None)
        dims.append(len(W[n]))
    dims.reverse()
    print(f"d={d} mod {p}: span dims n={d}..{N}: {dims}")
    print(f"d={d} mod-p certificate (span=ker=TheoremC at every weight): {ok}  ({time.time()-t0:.1f}s)")
    return ok

if __name__ == "__main__":
    mode = sys.argv[1]
    if mode == "exact":
        allok = all(run_exact(d) for d in range(int(sys.argv[2]), int(sys.argv[3]) + 1))
    else:
        p = int(sys.argv[4])
        allok = all(run_modp(d, p) for d in range(int(sys.argv[2]), int(sys.argv[3]) + 1))
    print("ALL_OK", allok)
